// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Caller h0;
    Caller h1;

    function setUp() public {
        c = new ModifierEntrancy();
        h0 = new Caller(address(c));
        h1 = new Caller(address(c));
    }

    function testFuzz_property(uint256 which) public {
        Caller h = (which % 2 == 0) ? h0 : h1;
        h.callAirDrop();
        // General rule: after a successful airDrop, the caller's balance is credited by 20.
        assertTrue(c.tokenBalance(address(h)) == 20);
    }
}

contract Caller {
    ModifierEntrancy c;
    constructor(address a) { c = ModifierEntrancy(a); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop() external { c.airDrop(); }
}
